import type { WalkLocation } from "@/types/location";
import type { WalkingRoute } from "@/types/navigation";
import { findPosition, loadRouteLegs } from "../../shared";
import { cafeName, pubGameCafes } from "./cafes";
import coordinatesFile from "./coordinates.json";
import routesFile from "./routes.json";

/**
 * What the shared navigation screen needs for Hidden Pubs 2.0. Imported only by
 * the (lazily loaded) café navigation, so the 37 pre-generated walking legs
 * (routes.json, generated by scripts/generate-walking-routes.mjs hidden-pubs/game)
 * are downloaded only when a team is on its way.
 */
const routeLegs = loadRouteLegs(routesFile);

/** A café as a navigation destination (the shared NavigationScreen works with WalkLocation). */
export function cafeDestination(cafeId: string, order: number): WalkLocation {
  return {
    id: cafeId,
    order,
    name: cafeName(cafeId),
    type: "pub",
    // Unknown (Café Barries): the screen then shows just the name.
    address: pubGameCafes[cafeId]?.address ?? "",
    ...findPosition(coordinatesFile, cafeId),
    description: "",
    content: [],
  };
}

/** The walking route between two cafés, or null (first café, or a café without a position yet). */
export function walkBetween(fromCafeId: string | undefined, toCafeId: string): WalkingRoute | null {
  if (!fromCafeId) return null;
  return routeLegs.find((leg) => leg.fromLocationId === fromCafeId && leg.toLocationId === toCafeId)?.route ?? null;
}
